import pandas as pd, numpy as np, warnings
warnings.filterwarnings('ignore')
R=pd.read_csv('validation/film_results.csv'); S=pd.read_csv('submissions.csv')
print(list(S.columns))
lab=[c for c in S.columns if S[c].astype(str).isin(['V12','FA','TP2']).sum()>=3][0]
pub=dict(zip(S[lab],S['public_lb']))
print('n',len(S),S.public_lb.value_counts().sort_index(ascending=False).head(9).to_dict())
print('top:',' '.join(f"{k}:{v}" for k,v in sorted(pub.items(),key=lambda x:-x[1])[:14]))
def arr(g):
    w=(g.edge_tp+g.edge_fp+g.edge_fn).to_numpy(float); return [w, w*g.adj.to_numpy(float), g.division_tp.to_numpy(float), (g.division_tp+g.division_fp+g.division_fn).to_numpy(float)]
def sc(a):
    w,wa,tp,c=a; return wa.sum()/w.sum()+(0.1*tp.sum()/c.sum() if c.sum()>0 else 0.0)
def bs(x,idx):
    w,wa,tp,c=[v[idx].sum(1) for v in x]; return wa/w+np.where(c>0,0.1*tp/np.maximum(c,1),0)
def run(lane,base,cand,npub=58,B=5000,emb=None):
    gb=R[(R.lane==lane)&(R.candidate==base)].set_index('film'); gc=R[(R.lane==lane)&(R.candidate==cand)].set_index('film')
    fl=sorted(set(gb.index)&set(gc.index))
    if emb: fl=[f for f in fl if gb.loc[f,'embryo']==emb]
    gb=gb.loc[fl]; gc=gc.loc[fl]; a=arr(gb); b=arr(gc); n=len(fl)
    rng=np.random.default_rng(7); i2=rng.integers(0,n,(B,npub)); sa=bs(a,i2); sb=bs(b,i2); dp=sb-sa
    rd=np.round(sb,3)-np.round(sa,3); d=sc(b)-sc(a); pd_=pub[cand]-pub[base]; sd=dp.std()
    print(f"{(lane+('/'+emb if emb else ''))[:16]:16s} {cand:>4s}-{base:<4s} n={n:3d} val={d:+.5f} | n{npub}: SDscore={sa.std():.4f} SDdiff={sd:.4f} pub={pd_:+.3f} ratio={(pd_/sd if sd>0 else float('nan')):+.2f} | P(tie)={np.mean(np.abs(rd)<5e-4):.2f} P(rd>0)={np.mean(rd>5e-4):.2f} P(rd<0)={np.mean(rd<-5e-4):.2f}")
    return sd
prs=[('FA','V12'),('TP2','V12'),('TAP','V12'),('FAS','V12'),('PR07','V12'),('TP2','FA')]
for lane in ['honest_oof','honest_oofm','farm']:
    for c,b in prs:
        if len(R[(R.lane==lane)&(R.candidate==c)]): run(lane,b,c)
print('--- by embryo / other public size')
for e in ['6bba']:
    for c,b in [('FA','V12'),('TP2','V12'),('TP2','FA')]: run('honest_oof',b,c,emb=e)
for c,b in [('TP2','V12'),('TAP','V12'),('FAS','V12'),('TP2','FA')]: run('farm',b,c,emb='44b6')
for npub in [40,100]:
    run('honest_oof','V12','FA',npub=npub); run('honest_oof','V12','TP2',npub=npub); run('farm','V12','TP2',npub=npub)
# max of k noise
for k in [5,6,10,40]: print('k',k,'sqrt(2lnk)=%.2f'%np.sqrt(2*np.log(k)),'E[max]~%.2f'%np.mean(np.max(np.random.default_rng(0).standard_normal((20000,k)),1)))
# divisions density: per 58 films
g=R[(R.lane=='honest_oof')&(R.candidate=='V12')]; h=R[(R.lane=='farm')&(R.candidate=='V12')]
for nm,x in [('oof114',g),('farm79',h)]:
    c=(x.division_tp+x.division_fp+x.division_fn).sum(); print(nm,'div events per 58 films=%.1f'%(c/len(x)*58),'TP per 58=%.1f'%(x.division_tp.sum()/len(x)*58),'one TP worth ~%.4f'%(0.1/(c/len(x)*58)))
