import pandas as pd, numpy as np, os, warnings
warnings.filterwarnings('ignore')
if os.path.exists('scratch_scores.csv'): os.remove('scratch_scores.csv'); print('removed scratch_scores.csv')
R=pd.read_csv('validation/film_results.csv'); S=pd.read_csv('submissions.csv'); pub=dict(zip(S.label,S.public_lb))
def arr(g):
    w=(g.edge_tp+g.edge_fp+g.edge_fn).to_numpy(float); return [w, w*g.adj.to_numpy(float), g.division_tp.to_numpy(float), (g.division_tp+g.division_fp+g.division_fn).to_numpy(float)]
def sc(a):
    w,wa,tp,c=a; return wa.sum()/w.sum()+(0.1*tp.sum()/c.sum() if c.sum()>0 else 0.0)
def bs(x,idx):
    w,wa,tp,c=[v[idx].sum(1) for v in x]; return wa/w+np.where(c>0,0.1*tp/np.maximum(c,1),0)
def get(l,c): return R[(R.lane==l)&(R.candidate==c)].set_index('film')
in114=set(get('honest_oof','V12').index)
def sub(lane,base,cand,films,tag,B=5000):
    gb=get(lane,base).loc[films]; gc=get(lane,cand).loc[films]; a=arr(gb); b=arr(gc); n=len(films)
    rng=np.random.default_rng(3); i=rng.integers(0,n,(B,n)); bd=bs(b,i)-bs(a,i); d=sc(b)-sc(a)
    dadj=gc.adj.values-gb.adj.values
    print(f"{lane}/{tag} {cand}-{base} n={n} d={d:+.5f} CI[{np.percentile(bd,2.5):+.4f},{np.percentile(bd,97.5):+.4f}] p+={np.mean(bd>0):.2f} div {int(gb.division_tp.sum())}/{int(gb.division_fp.sum())}/{int(gb.division_fn.sum())}->{int(gc.division_tp.sum())}/{int(gc.division_fp.sum())}/{int(gc.division_fn.sum())} adj+/-={int((dadj>1e-9).sum())}/{int((dadj<-1e-9).sum())}")
fm=get('farm','V12'); out=[f for f in fm.index if f not in in114]; out44=[f for f in out if fm.loc[f,'embryo']=='44b6']; out6=[f for f in out if fm.loc[f,'embryo']=='6bba']
for c,b in [('TP2','V12'),('TAP','V12'),('FAS','V12'),('FA','V12'),('TP2','FA')]:
    sub('farm',b,c,out,'out114'); sub('farm',b,c,out44,'out114_44b6')
sub('farm','V12','TP2',out6,'out114_6bba')
print('== observed public vs lane forecast, z=(pub-val)/SDdiff58 ; with rounding slack +-0.001')
def z(lane,base,cand,npub=58,B=5000):
    gb=get(lane,base); gc=get(lane,cand); fl=sorted(set(gb.index)&set(gc.index)); a=arr(gb.loc[fl]); b=arr(gc.loc[fl])
    rng=np.random.default_rng(7); i=rng.integers(0,len(fl),(B,npub)); sa=bs(a,i); sb=bs(b,i); rd=np.round(sb,3)-np.round(sa,3); o=pub[cand]-pub[base]
    print(f"{lane:11s} {cand}-{base}: val={sc(b)-sc(a):+.4f} pub={o:+.3f} z={(o-(sc(b)-sc(a)))/(sb-sa).std():+.1f} P(rounded diff<=obs)={np.mean(rd<=o+5e-4):.3f} P(>=obs)={np.mean(rd>=o-5e-4):.3f}")
for lane in ['honest_oof','honest_oofm','farm']:
    for c in ['FA','TP2','TAP','FAS']: z(lane,'V12',c)
z('cache46','SV','LNK'); z('honest_a','SV','LNK'); z('cache46','E1','IF'); z('honest_a','E1','IF'); z('cache46','E1','D08'); z('honest_a','E1','D08'); z('evalpod','LNK','V12')
